import {
	cloneVNode,
	computed,
	defineComponent,
	h,
	inject,
	nextTick,
	onBeforeUnmount,
	provide,
	ref,
	useId,
	watch,
	Teleport,
	type ComputedRef,
	type InjectionKey,
	type PropType,
} from 'vue';
import type { ButtonSize, ButtonVariant } from '../lib/core';
import { alertDialogStyleKeys, getAlertDialogState } from '../lib/core';
import type { AlertDialogSize } from '../lib/core';
import { Button } from '../button';
import { usePortalContainer, type PortalContainer } from '../portal';
import styles from './alert-dialog.module.scss';

interface AlertDialogContextValue {
	open: boolean;
	setOpen: (open: boolean) => void;
	close: () => void;
	titleId: string;
	descriptionId: string;
}

type AlertDialogContext = ComputedRef<AlertDialogContextValue>;

const AlertDialogContextKey: InjectionKey<AlertDialogContext> = Symbol('tile-alert-dialog');

function composeEventHandlers(...handlers: Array<unknown>): (event: Event) => void {
	return (event: Event) => {
		for (const handler of handlers) {
			if (!handler) {
				continue;
			}

			const list = Array.isArray(handler) ? handler : [handler];

			for (const item of list) {
				if (typeof item === 'function') {
					item(event);
				}
			}
		}
	};
}

export const AlertDialog = defineComponent({
	name: 'AlertDialog',
	props: {
		open: { type: Boolean, default: undefined },
		defaultOpen: { type: Boolean, default: false },
	},
	emits: ['update:open'],
	setup(props, { emit, slots }) {
		const internalOpen = ref(props.defaultOpen);
		const isOpen = computed(() => (props.open !== undefined ? props.open : internalOpen.value));
		const baseId = useId();
		const titleId = `${baseId}-title`;
		const descriptionId = `${baseId}-description`;

		function setOpen(next: boolean) {
			if (props.open === undefined) {
				internalOpen.value = next;
			}

			emit('update:open', next);
		}

		function close() {
			setOpen(false);
		}

		const context = computed<AlertDialogContextValue>(() => ({
			open: isOpen.value,
			setOpen,
			close,
			titleId,
			descriptionId,
		}));

		provide(AlertDialogContextKey, context);

		return () => slots.default?.();
	},
});

export const AlertDialogTrigger = defineComponent({
	name: 'AlertDialogTrigger',
	props: {
		asChild: { type: Boolean, default: false },
	},
	setup(props, { slots, attrs }) {
		const contextValue = inject(AlertDialogContextKey);
		if (!contextValue) {
			throw new Error('AlertDialogTrigger must be used within <AlertDialog>.');
		}
		const context: AlertDialogContext = contextValue;

		function handleOpen() {
			context.value.setOpen(true);
		}

		return () => {
			const children = slots.default?.();
			const attrOnClick = (attrs as Record<string, unknown>).onClick;

			if (props.asChild) {
				const firstChild = Array.isArray(children) ? children[0] : children;

				if (firstChild) {
					const childProps = (firstChild.props ?? {}) as Record<string, unknown>;
					return cloneVNode(firstChild, {
						...attrs,
						onClick: composeEventHandlers(attrOnClick, childProps.onClick, handleOpen),
					});
				}
			}

			return h('button', { type: 'button', ...attrs, onClick: composeEventHandlers(attrOnClick, handleOpen) }, children);
		};
	},
});

export const AlertDialogOverlay = defineComponent({
	name: 'AlertDialogOverlay',
	setup(_props, { slots, attrs }) {
		const contextValue = inject(AlertDialogContextKey);
		if (!contextValue) {
			throw new Error('AlertDialogOverlay must be used within <AlertDialog>.');
		}
		const context: AlertDialogContext = contextValue;

		return () => {
			if (!context.value.open) {
				return null;
			}

			return h(
				'div',
				{
					...attrs,
					'data-state': getAlertDialogState(context.value.open),
					class: [styles[alertDialogStyleKeys.overlay], attrs.class],
					onClick: composeEventHandlers((attrs as Record<string, unknown>).onClick, () => context.value.close()),
				},
				slots.default?.(),
			);
		};
	},
});

export const AlertDialogContent = defineComponent({
	name: 'AlertDialogContent',
	props: {
		size: {
			type: String as PropType<AlertDialogSize>,
			default: 'default',
		},
		container: { type: Object as PropType<PortalContainer>, default: null },
	},
	setup(props, { slots, attrs }) {
		const portalContainer = usePortalContainer(() => props.container);
		const contextValue = inject(AlertDialogContextKey);
		if (!contextValue) {
			throw new Error('AlertDialogContent must be used within <AlertDialog>.');
		}
		const context: AlertDialogContext = contextValue;
		const contentRef = ref<HTMLElement | null>(null);
		const previousOverflow = ref('');
		let previouslyFocused: HTMLElement | null = null;

		function handleKeyDown(event: KeyboardEvent) {
			if (event.key === 'Escape') {
				context.value.close();
				return;
			}

			if (event.key === 'Tab') {
				const container = contentRef.value;
				if (!container) {
					return;
				}
				const focusables = Array.from(
					container.querySelectorAll<HTMLElement>(
						'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])',
					),
				).filter((el) => el.getClientRects().length > 0);
				if (focusables.length === 0) {
					event.preventDefault();
					return;
				}
				const first = focusables[0];
				const last = focusables[focusables.length - 1];
				const active = document.activeElement;

				if (event.shiftKey) {
					if (active === first || active === container || !container.contains(active)) {
						event.preventDefault();
						last.focus();
					}
				} else if (active === last || !container.contains(active)) {
					event.preventDefault();
					first.focus();
				}
			}
		}

		watch(
			() => context.value.open,
			(open) => {
				if (typeof document === 'undefined') {
					return;
				}

				if (open) {
					previouslyFocused = document.activeElement as HTMLElement | null;
					previousOverflow.value = document.body.style.overflow;
					document.body.style.overflow = 'hidden';
					document.addEventListener('keydown', handleKeyDown);
					nextTick(() => {
						contentRef.value?.focus();
					});
				} else {
					document.removeEventListener('keydown', handleKeyDown);
					document.body.style.overflow = previousOverflow.value;
					previouslyFocused?.focus();
				}
			},
			{ immediate: true },
		);

		onBeforeUnmount(() => {
			document.removeEventListener('keydown', handleKeyDown);
			document.body.style.overflow = previousOverflow.value;
			previouslyFocused?.focus();
		});

		return () => {
			if (!context.value.open) {
				return null;
			}

			const userClass = attrs.class;
			const contentAttrs = { ...attrs };
			delete contentAttrs.class;

			return h(Teleport, { to: portalContainer.value }, [
				h('div', {
					'data-state': getAlertDialogState(context.value.open),
					class: styles[alertDialogStyleKeys.overlay],
					onClick: () => context.value.close(),
				}),
				h(
					'div',
					{
						...contentAttrs,
						ref: contentRef,
						role: 'alertdialog',
						'aria-modal': 'true',
						'aria-labelledby': context.value.titleId,
						'aria-describedby': context.value.descriptionId,
						tabindex: -1,
						'data-state': getAlertDialogState(context.value.open),
						'data-size': props.size,
						class: [styles[alertDialogStyleKeys.content], userClass],
					},
					slots.default?.(),
				),
			]);
		};
	},
});

export const AlertDialogHeader = defineComponent({
	name: 'AlertDialogHeader',
	setup(_props, { slots, attrs }) {
		return () => h('div', { ...attrs, class: [styles[alertDialogStyleKeys.header], attrs.class] }, slots.default?.());
	},
});

export const AlertDialogFooter = defineComponent({
	name: 'AlertDialogFooter',
	setup(_props, { slots, attrs }) {
		return () => h('div', { ...attrs, class: [styles[alertDialogStyleKeys.footer], attrs.class] }, slots.default?.());
	},
});

export const AlertDialogTitle = defineComponent({
	name: 'AlertDialogTitle',
	setup(_props, { slots, attrs }) {
		const contextValue = inject(AlertDialogContextKey);
		if (!contextValue) {
			throw new Error('AlertDialogTitle must be used within <AlertDialog>.');
		}
		const context: AlertDialogContext = contextValue;

		return () => h('h2', { ...attrs, id: context.value.titleId, class: [styles[alertDialogStyleKeys.title], attrs.class] }, slots.default?.());
	},
});

export const AlertDialogDescription = defineComponent({
	name: 'AlertDialogDescription',
	setup(_props, { slots, attrs }) {
		const contextValue = inject(AlertDialogContextKey);
		if (!contextValue) {
			throw new Error('AlertDialogDescription must be used within <AlertDialog>.');
		}
		const context: AlertDialogContext = contextValue;

		return () => h('p', { ...attrs, id: context.value.descriptionId, class: [styles[alertDialogStyleKeys.description], attrs.class] }, slots.default?.());
	},
});

export const AlertDialogAction = defineComponent({
	name: 'AlertDialogAction',
	props: {
		variant: {
			type: String as PropType<ButtonVariant>,
			default: 'default',
		},
		size: {
			type: String as PropType<ButtonSize>,
			default: 'default',
		},
	},
	setup(props, { slots, attrs }) {
		const contextValue = inject(AlertDialogContextKey);
		if (!contextValue) {
			throw new Error('AlertDialogAction must be used within <AlertDialog>.');
		}
		const context: AlertDialogContext = contextValue;

		function handleAction() {
			context.value.close();
		}

		return () =>
			h(
				Button,
				{
					...attrs,
					type: 'button',
					variant: props.variant,
					size: props.size,
					onClick: composeEventHandlers((attrs as Record<string, unknown>).onClick, handleAction),
				},
				{ default: () => slots.default?.() },
			);
	},
});

export const AlertDialogCancel = defineComponent({
	name: 'AlertDialogCancel',
	props: {
		variant: {
			type: String as PropType<ButtonVariant>,
			default: 'outline',
		},
		size: {
			type: String as PropType<ButtonSize>,
			default: 'default',
		},
	},
	setup(props, { slots, attrs }) {
		const contextValue = inject(AlertDialogContextKey);
		if (!contextValue) {
			throw new Error('AlertDialogCancel must be used within <AlertDialog>.');
		}
		const context: AlertDialogContext = contextValue;

		function handleCancel() {
			context.value.close();
		}

		return () =>
			h(
				Button,
				{
					...attrs,
					type: 'button',
					variant: props.variant,
					size: props.size,
					onClick: composeEventHandlers((attrs as Record<string, unknown>).onClick, handleCancel),
				},
				{ default: () => slots.default?.() },
			);
	},
});

export default AlertDialog;

@use '../../../styles/variables/colors' as *;

// 半透明遮罩
.overlay {
	position: fixed;
	inset: 0;
	z-index: $z-modal;
	background-color: var(--tile-alert-dialog-overlay, $overlay);

	&[data-state='open'] {
		animation: alert-dialog-overlay-in $transition-normal;
	}

	&[data-state='closed'] {
		opacity: 0;
	}
}

@keyframes alert-dialog-overlay-in {
	from {
		opacity: 0;
	}

	to {
		opacity: 1;
	}
}

// 弹层内容面板
.content {
	position: fixed;
	top: var(--tile-alert-dialog-top, 50%);
	left: 50%;
	z-index: $z-modal;
	display: grid;
	width: 100%;
	max-width: calc(100% - 2rem);
	transform: translate(-50%, var(--tile-alert-dialog-translate-y, -50%));
	gap: $spacing-4;
	border: 1px solid var(--tile-alert-dialog-border, $border);
	border-radius: var(--tile-alert-dialog-radius, $radius-lg);
	background-color: var(--tile-alert-dialog-background, $card);
	color: $card-foreground;
	padding: var(--tile-alert-dialog-padding, $spacing-6);
	box-shadow: var(--tile-alert-dialog-shadow, $shadow-lg);
	outline: none;

	@media (min-width: 640px) {
		top: var(--tile-alert-dialog-top-desktop, 50%);
		max-width: var(--tile-alert-dialog-max-width, 32rem);
	}

	&[data-size='sm'] {
		max-width: var(--tile-alert-dialog-sm-max-width, 20rem);
	}

	&[data-state='open'] {
		animation: alert-dialog-content-in $transition-normal;
	}

	&[data-state='closed'] {
		opacity: 0;
		transform: translate(-50%, var(--tile-alert-dialog-translate-y, -50%)) scale(0.95);
	}
}

@keyframes alert-dialog-content-in {
	from {
		opacity: 0;
		transform: translate(-50%, var(--tile-alert-dialog-translate-y, -50%)) scale(0.95);
	}

	to {
		opacity: 1;
		transform: translate(-50%, var(--tile-alert-dialog-translate-y, -50%)) scale(1);
	}
}

.header {
	display: flex;
	flex-direction: column;
	align-items: center;
	gap: $spacing-1_5;
	text-align: center;

	@media (min-width: 640px) {
		.content[data-size='default'] & {
			align-items: flex-start;
			text-align: left;
		}
	}
}

.footer {
	display: flex;
	flex-direction: column-reverse;
	gap: $spacing-2;

	@media (min-width: 640px) {
		.content[data-size='default'] & {
			flex-direction: row;
			justify-content: flex-end;
		}
	}
}

.title {
	margin: 0;
	font-size: var(--tile-alert-dialog-title-size, $text-lg);
	font-weight: $font-semibold;
	line-height: var(--tile-alert-dialog-title-leading, $leading-tight);
	color: $foreground;
}

.description {
	margin: 0;
	font-size: var(--tile-alert-dialog-description-size, $text-sm);
	line-height: $leading-normal;
	color: var(--tile-alert-dialog-description-color, $muted-foreground);
}
